Client.code:
import { Client } from "tls-forge";

const client = new Client({ profile: "chrome", timeout: 45000 });
const response = await client.get("https://example.com/");
console.log(response.status);
client.close();

Client.get().code:
const response = await client.get("https://example.com/");
console.log(response.status, response.url);
console.log(response.headers["content-type"]);

Client.post().code:
const response = await client.post(
  "https://httpbin.org/post",
  '{"hello":"world"}',
  {
    headers: { "content-type": "application/json" },
    browserContext: { kind: "fetch", initiator: "https://httpbin.org/" },
  },
);
console.log(response.body);

Client.request().code:
const response = await client.request({
  url: "https://httpbin.org/anything",
  method: "PUT",
  body: '{"id": 1}',
  headers: { "content-type": "application/json" },
  browserContext: { kind: "fetch", initiator: "https://httpbin.org/" },
});
const data = JSON.parse(response.body);
console.log(response.status, data.method, data.json);

Client.hello().code:
const hello = await client.hello();
console.log(hello.protocol, hello.engine_major, hello.version);
console.log(hello.capabilities.includes("browser_context"));

Client.close().code:
const client = new Client({ profile: "chrome" });
try {
  const response = await client.get("https://example.com/");
} finally {
  client.close();
}

